selG.value="SIMP-TIP-2"; selL.value="P1000";

function drawSection(gid){
  const svg = document.getElementById('xsec');
  const meta = GEOMETA[gid], p = meta.params;
  const NS='http://www.w3.org/2000/svg';
  svg.innerHTML='';
  const cap = document.getElementById('xsecCap');
  if(meta.family==='SIMP freeform'){
    cap.textContent='Optimized topology (plan view, 500 x 100 mm)';
    const bm = TOPO[gid], rows=bm.length, cols=bm[0].length;
    const cw=210/cols, ch=110/rows;
    for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){
      if(bm[r][c]==='1'){const rect=document.createElementNS(NS,'rect');
        rect.setAttribute('x',5+c*cw);rect.setAttribute('y',10+r*ch);
        rect.setAttribute('width',cw+0.4);rect.setAttribute('height',ch+0.4);
        rect.setAttribute('fill','#6D8196');svg.appendChild(rect);}}
    return;
  }
  cap.textContent='Cross-section (to scale, mm)';
  let w,h,el;
  if(meta.family==='Solid rectangle'){w=p.b;h=p.h;
    const s=Math.min(200/w,105/h),ox=110-w*s/2,oy=10+(105-h*s)/2;
    el=document.createElementNS(NS,'rect');
    el.setAttribute('x',ox);el.setAttribute('y',oy);el.setAttribute('width',w*s);el.setAttribute('height',h*s);
  } else if(meta.family==='Circular hollow'){
    const s=Math.min(200/p.Do,105/p.Do),cx=110,cy=10+105/2;
    el=document.createElementNS(NS,'path');
    el.setAttribute('d',`M ${cx-p.Do*s/2} ${cy} a ${p.Do*s/2} ${p.Do*s/2} 0 1 0 ${p.Do*s} 0 a ${p.Do*s/2} ${p.Do*s/2} 0 1 0 ${-p.Do*s} 0 Z M ${cx-p.Di*s/2} ${cy} a ${p.Di*s/2} ${p.Di*s/2} 0 1 1 ${p.Di*s} 0 a ${p.Di*s/2} ${p.Di*s/2} 0 1 1 ${-p.Di*s} 0 Z`);
    el.setAttribute('fill-rule','evenodd');
  } else {
    let pts=[];
    if(meta.family==='I-beam'){const{h,bf,tf,tw}=p;
      pts=[[0,0],[bf,0],[bf,tf],[(bf+tw)/2,tf],[(bf+tw)/2,h-tf],[bf,h-tf],[bf,h],[0,h],[0,h-tf],[(bf-tw)/2,h-tf],[(bf-tw)/2,tf],[0,tf]];
      w=bf;}
    else if(meta.family==='Hollow rectangle'){const{h,b,t}=p;w=b;
      const s=Math.min(200/b,105/h),ox=110-b*s/2,oy=10+(105-h*s)/2;
      el=document.createElementNS(NS,'path');
      el.setAttribute('d',`M ${ox} ${oy} h ${b*s} v ${h*s} h ${-b*s} Z M ${ox+t*s} ${oy+t*s} h ${(b-2*t)*s} v ${(h-2*t)*s} h ${-(b-2*t)*s} Z`);
      el.setAttribute('fill-rule','evenodd');
      el.setAttribute('fill','#6D8196');el.setAttribute('stroke','#4A4A4A');el.setAttribute('stroke-width','1');
      svg.appendChild(el);return;}
    else if(meta.family==='T-section'){const{h,bf,tf,tw}=p;w=bf;
      pts=[[(bf-tw)/2,0],[(bf+tw)/2,0],[(bf+tw)/2,h-tf],[bf,h-tf],[bf,h],[0,h],[0,h-tf],[(bf-tw)/2,h-tf]];
      pts=pts.map(([x,y])=>[x,h-y]);}
    else if(meta.family==='Trapezoidal'){const{h,b_bottom,b_top}=p;w=Math.max(b_bottom,b_top);
      pts=[[(w-b_bottom)/2,0],[(w+b_bottom)/2,0],[(w+b_top)/2,h],[(w-b_top)/2,h]];
      pts=pts.map(([x,y])=>[x,h-y]);}
    const s=Math.min(200/w,105/h);
    const d=pts.map(([x,y],i)=>`${i?'L':'M'} ${(110-w*s/2+x*s).toFixed(1)} ${(10+(105-h*s)/2+y*s).toFixed(1)}`).join(' ')+' Z';
    el=document.createElementNS(NS,'path');el.setAttribute('d',d);
  }
  el.setAttribute('fill','#6D8196');el.setAttribute('stroke','#4A4A4A');el.setAttribute('stroke-width','1');
  svg.appendChild(el);
}

function updateExplorer(){
  const g=selG.value,l=selL.value,r=LOOKUP[g+"|"+l];
  if(r){document.getElementById('stVM').textContent=r[3].toLocaleString();
    document.getElementById('stDefl').textContent=r[4].toLocaleString();
    const sf=document.getElementById('stSF');sf.textContent=r[5];
    sf.style.color=r[5]>=1?'#3F5062':(r[5]>=0.3?'#6B6A50':'#a11');
    document.getElementById('stI').textContent=r[8].toLocaleString();
    document.getElementById('stMEI').textContent=r[6];
    document.getElementById('stUnif').textContent=r[7].toLocaleString();}
  const m=GEOMETA[g];
  document.getElementById('geomDesc').textContent=`${g} · ${m.family} · ${m.label} · structural steel, 100 cm³, 500 mm span`;
  drawSection(g);
}
selG.addEventListener('change',updateExplorer);
selL.addEventListener('change',updateExplorer);
updateExplorer();

/* ---------- scroll-spy ---------- */
const navLinks=[...document.querySelectorAll('#nav a')];
const spy=new IntersectionObserver(entries=>{
  entries.forEach(e=>{if(e.isIntersecting){
    navLinks.forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+e.target.id));}});
},{rootMargin:'-35% 0px -60% 0px'});
navLinks.forEach(a=>{const s=document.querySelector(a.getAttribute('href'));if(s)spy.observe(s);});

